import{_ as p,r as o,o as i,c,e as n,a as t,s as l}from"./chunks/framework.CXcwiNg-.js";const A=JSON.parse('{"title":"Приложение - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Application container","slug":"application-container","link":"#application-container","children":[{"level":4,"title":"Помещение в контейнер","slug":"помещение-в-контеинер","link":"#помещение-в-контеинер","children":[]},{"level":4,"title":"Извлечение из контейнера","slug":"извлечение-из-контеинера","link":"#извлечение-из-контеинера","children":[]},{"level":4,"title":"Помещение shared (\\"разделяемого\\") типа в контейнер","slug":"помещение-shared-разделяемого-типа-в-контеинер","link":"#помещение-shared-разделяемого-типа-в-контеинер","children":[]},{"level":4,"title":"Помещение готового экземпляра в контейнер","slug":"помещение-готового-экземпляра-в-контеинер","link":"#помещение-готового-экземпляра-в-контеинер","children":[]},{"level":4,"title":"Связывание интерфейса и реализации","slug":"связывание-интерфеиса-и-реализации","link":"#связывание-интерфеиса-и-реализации","children":[]},{"level":3,"title":"Где регистрировать связывания?","slug":"где-регистрировать-связывания","link":"#где-регистрировать-связывания","children":[]}]},{"level":2,"title":"Service providers","slug":"service-providers","link":"#service-providers","children":[{"level":4,"title":"Создание сервис-провайдера","slug":"создание-сервис-проваидера","link":"#создание-сервис-проваидера","children":[]},{"level":4,"title":"Регистрация сервис-провайдеров во время выполнения","slug":"регистрация-сервис-проваидеров-во-время-выполнения","link":"#регистрация-сервис-проваидеров-во-время-выполнения","children":[]}]},{"level":2,"title":"Application events","slug":"application-events","link":"#application-events","children":[{"level":4,"title":"События запроса","slug":"события-запроса","link":"#события-запроса","children":[]},{"level":4,"title":"События контейнера","slug":"события-контеинера","link":"#события-контеинера","children":[]}]},{"level":2,"title":"Application helpers","slug":"application-helpers","link":"#application-helpers","children":[{"level":4,"title":"Получение текущей среды приложения","slug":"получение-текущеи-среды-приложения","link":"#получение-текущеи-среды-приложения","children":[]},{"level":4,"title":"Определение контекста выполнения","slug":"определение-контекста-выполнения","link":"#определение-контекста-выполнения","children":[]}]}],"relativePath":"1.x/ru/services/application.md","filePath":"1.x/ru/services/application.md"}'),s={name:"1.x/ru/services/application.md"};function d(h,e,u,v,f,g){const r=o("pre-heading"),a=o("post-heading");return i(),c("div",null,[n(r),e[0]||(e[0]=t("h1",null,"Приложение",-1)),n(a),e[1]||(e[1]=l(`<p><a name="app-container" class="anchor"></a></p><h2 id="application-container"><a href="#application-container" class="header-anchor">#</a> Application container</h2><p>Класс-контейнер обратного управления IoC (Inversion of Control) - мощное средство для управления зависимостями классов. Внедрение зависимостей - это способ исключения вшитых (hardcoded) взаимосвязей классов. Вместо этого зависимости определяются во время выполнения, что даёт бОльшую гибкость благодаря тому, что они могут быть легко изменены.</p><h4 id="помещение-в-контеинер"><a href="#помещение-в-контеинер" class="header-anchor">#</a> Помещение в контейнер</h4><p>Есть два способа, которыми IoC-контейнер разрешает зависимости: через функцию-замыкание и через автоматическое определение.</p><p>Для начала давайте посмотрим замыкания. Поместим нечто в контейнер и назовём это <code>foo</code>:</p><pre><code>App::bind(&#39;foo&#39;, function($app) {
    return new FooBar;
});
</code></pre><h4 id="извлечение-из-контеинера"><a href="#извлечение-из-контеинера" class="header-anchor">#</a> Извлечение из контейнера</h4><pre><code>$value = App::make(&#39;foo&#39;);
</code></pre><p>При вызове метода <code>App::make</code> вызывается соответствующая функция-замыкание и возвращается результат её вызова.</p><h4 id="помещение-shared-разделяемого-типа-в-контеинер"><a href="#помещение-shared-разделяемого-типа-в-контеинер" class="header-anchor">#</a> Помещение shared (&quot;разделяемого&quot;) типа в контейнер</h4><p>Иногда вам может понадобиться поместить в контейнер нечто, что должно быть создано только один раз, а все последующие вызовы должны возвратить тот же объект.</p><pre><code>App::singleton(&#39;foo&#39;, function() {
    return new FooBar;
});
</code></pre><h4 id="помещение-готового-экземпляра-в-контеинер"><a href="#помещение-готового-экземпляра-в-контеинер" class="header-anchor">#</a> Помещение готового экземпляра в контейнер</h4><p>Вы также можете поместить уже созданный экземпляр объекта в контейнер, используя метод <code>instance</code>:</p><pre><code>$foo = new Foo;

App::instance(&#39;foo&#39;, $foo);
</code></pre><h4 id="связывание-интерфеиса-и-реализации"><a href="#связывание-интерфеиса-и-реализации" class="header-anchor">#</a> Связывание интерфейса и реализации</h4><p>В некоторых случаях класс может принимать экземпляр интерфейса, а не сам объект. В этом случае нужно использовать метод <code>App::bind</code> для извещения контейнера о том, какая именно зависимость должна быть внедрена.</p><pre><code>App::bind(&#39;UserRepositoryInterface&#39;, &#39;DbUserRepository&#39;);
</code></pre><p>Теперь посмотрим на следующий контроллер:</p><pre><code>$users = App::make(&#39;UserRepositoryInterface&#39;);
</code></pre><p>Благодаря тому, что мы связали <code>UserRepositoryInterface</code> с &quot;настоящим&quot; классом, <code>DbUserRepository</code>, он будет автоматически встроен в контроллер при его создании.</p><p><a name="where-to-register" class="anchor"></a></p><h3 id="где-регистрировать-связывания"><a href="#где-регистрировать-связывания" class="header-anchor">#</a> Где регистрировать связывания?</h3><p>Вышеописанные биндинги (связывание) в IoC, как и обработчики событий, обычно попадают в категорию «код начальной загрузки». Другими словами, они подготавливают ваше приложение для обработки запросов и должны быть выполнены перед вызовом маршрутизации или контроллера. Поэтому наиболее подходящее для них место - метод <code>boot</code> в <a href="./../plugin/registration.html#registration-methods">файле регистрации плагина</a>. Также Вы можете использовать файл <strong>init.php</strong>, который должен находится в корне папки плагина, для того, чтобы описать логику регистрации IoC.</p><p><a name="service-providers" class="anchor"></a></p><h2 id="service-providers"><a href="#service-providers" class="header-anchor">#</a> Service providers</h2><p>Сервис-провайдеры (service providers, &quot;поставщики услуг&quot;) - отличный способ группировки схожих регистраций в IoC в одном месте. Их можно рассматривать как начальный запуск компонентов вашего приложения. Внутри поставщика услуг вы можете зарегистрировать драйвер авторизации, классы-хранилища вашего приложения или даже собственную консольную Artisan-команду.</p><p>Фактически, <a href="./../plugin/registration.html">файлы регистрации плагина</a> наследуют сервис-провайдеры, а большинство основных компонентов включают их в себя. Все зарегистрированные сервис-провайдеры для вашего приложения перечислены в массиве <code>providers</code> в файле с настройками <code>config/app.php</code>.</p><h4 id="создание-сервис-проваидера"><a href="#создание-сервис-проваидера" class="header-anchor">#</a> Создание сервис-провайдера</h4><p>Для создания нового сервис-провайдера просто наследуйте класс <code>October\\Rain\\Support\\ServiceProvider</code> и определите метод <code>register</code>:</p><pre><code>use October\\Rain\\Support\\ServiceProvider;

class FooServiceProvider extends ServiceProvider
{

    public function register()
    {
        $this-&gt;app-&gt;bind(&#39;foo&#39;, function() {
            return new Foo;
        });
    }

}
</code></pre><p>Заметьте, что внутри метода <code>register</code> IoC-контейнер приложения доступен в свойстве <code>$this-&gt;app</code>. Как только вы создали провайдера и готовы зарегистрировать его в своём приложении, просто добавьте его в массив <code>providers</code> в файле с настройками приложения.</p><h4 id="регистрация-сервис-проваидеров-во-время-выполнения"><a href="#регистрация-сервис-проваидеров-во-время-выполнения" class="header-anchor">#</a> Регистрация сервис-провайдеров во время выполнения</h4><p>Вы можете зарегистрировать сервис-провайдеры &quot;на лету&quot;, используя метод <code>App::register</code>:</p><pre><code>App::register(&#39;FooServiceProvider&#39;);
</code></pre><p><a name="application-events" class="anchor"></a></p><h2 id="application-events"><a href="#application-events" class="header-anchor">#</a> Application events</h2><h4 id="события-запроса"><a href="#события-запроса" class="header-anchor">#</a> События запроса</h4><p>Вы можете зарегистрировать специальные события до того, как запрос будет отправлен при помощи методов <code>before</code> и <code>after</code>:</p><pre><code>App::before(function ($request) {
    // Code to execute before the request is routed
});

App::after(function ($request) {
    // Code to execute after the request is routed
});
</code></pre><h4 id="события-контеинера"><a href="#события-контеинера" class="header-anchor">#</a> События контейнера</h4><p>IoC-контейнер запускает событие каждый раз при извлечении объекта. Вы можете отслеживать его с помощью метода <code>resolving</code>:</p><pre><code>App::resolving(function ($object, $app) {
    // Called when container resolves object of any type...
});

App::resolving(&#39;foo&#39;, function ($fooBar, $app) {
    // Called when container resolves objects using hint &quot;foo&quot;...
});

App::resolving(&#39;Acme\\Blog\\Classes\\FooBar&#39;, function ($fooBar, $app) {
    // Called when container resolves objects of type &quot;FooBar&quot;...
});
</code></pre><p>Созданный объект передаётся в функцию-замыкание в виде параметра.</p><p><a name="application-helpers" class="anchor"></a></p><h2 id="application-helpers"><a href="#application-helpers" class="header-anchor">#</a> Application helpers</h2><h4 id="получение-текущеи-среды-приложения"><a href="#получение-текущеи-среды-приложения" class="header-anchor">#</a> Получение текущей среды приложения</h4><p>Вы можете использовать метод <code>environment</code> для получения текущей среды:</p><pre><code>// production
App::environment();
</code></pre><h4 id="определение-контекста-выполнения"><a href="#определение-контекста-выполнения" class="header-anchor">#</a> Определение контекста выполнения</h4><p>Используйте метод <code>runningInBackend</code>, чтобы узнать: выполняется ли текущий запрос в административной части сайта:</p><pre><code>App::runningInBackend();
</code></pre><p>Используйте метод <code>runningInConsole</code>, чтобы проверить: выполняется ли текущий запрос в <a href="./../console/commands.html">командной строке</a>:</p><pre><code>App::runningInConsole();
</code></pre>`,55))])}const _=p(s,[["render",d]]);export{A as __pageData,_ as default};
